const { app, BrowserWindow, ipcMain, screen, dialog, shell, Notification } = require("electron");
const fs = require("fs");
const os = require("os");
const path = require("path");

let win = null;
let dragState = null;

/** Window / taskbar icon, generated by tools/make_icon.py. */
const APP_ICON = path.join(__dirname, "assets", "icon.png");

/**
 * The directory the folder button opens before the user picks their own.
 *
 * Deliberately derived at runtime instead of hardcoded: an absolute path baked
 * into the source only ever works on the machine that wrote it. Falls back to
 * the home directory when the platform reports no Documents folder.
 */
function defaultOpenDir() {
  try {
    return app.getPath("documents");
  } catch (e) {
    return os.homedir();
  }
}

// 默认位置：屏幕右侧、中上方（harness 浏览器窗口一般偏左，右侧留出来给鲸鱼娘）
function defaultPosition() {
  const wa = screen.getPrimaryDisplay().workArea;
  const W = 288;
  return {
    x: wa.x + wa.width - W - 24,
    y: wa.y + Math.round(wa.height * 0.18)
  };
}

// 记忆上次拖动的位置，下次启动还原（夹在屏幕工作区内）
function loadPosition() {
  try {
    const raw = fs.readFileSync(path.join(app.getPath("userData"), "window-pos.json"), "utf8");
    const { x, y } = JSON.parse(raw);
    if (typeof x === "number" && typeof y === "number") {
      const wa = screen.getPrimaryDisplay().workArea;
      const W = 288;
      const H = 300;
      return {
        x: Math.min(Math.max(x, wa.x), wa.x + wa.width - W),
        y: Math.min(Math.max(y, wa.y), wa.y + wa.height - H)
      };
    }
  } catch (e) { /* first run or unreadable -> default */ }
  return defaultPosition();
}

function savePosition() {
  if (!win) return;
  const [x, y] = win.getPosition();
  try {
    fs.writeFileSync(path.join(app.getPath("userData"), "window-pos.json"), JSON.stringify({ x, y }));
  } catch (e) { /* non-fatal */ }
}

function createWindow() {
  const pos = loadPosition();
  win = new BrowserWindow({
    x: pos.x,
    y: pos.y,
    width: 288,
    height: 300,
    icon: APP_ICON,
    transparent: true,
    frame: false,
    resizable: false,
    alwaysOnTop: true,
    skipTaskbar: true,
    hasShadow: false,
    fullscreenable: false,
    webPreferences: {
      nodeIntegration: true,
      contextIsolation: false
    }
  });
  win.setAlwaysOnTop(true, "screen-saver");
  // 透明区域默认鼠标穿透：只有悬停到鲸鱼娘/按钮/单词本上时才接管点击
  win.setIgnoreMouseEvents(true, { forward: true });
  win.loadFile("index.html");
}

ipcMain.on("ignore-mouse", (_e, ignore) => {
  if (win) win.setIgnoreMouseEvents(!!ignore, { forward: true });
});

ipcMain.on("quit", () => app.quit());
ipcMain.on("drag-start", (_e, { x, y }) => {
  if (!win) return;
  const [wx, wy] = win.getPosition();
  dragState = { x, y, wx, wy };
});
ipcMain.on("drag-move", (_e, { x, y }) => {
  if (!dragState || !win) return;
  win.setPosition(dragState.wx + (x - dragState.x), dragState.wy + (y - dragState.y));
});
ipcMain.on("drag-end", () => { dragState = null; savePosition(); });

// ── 屏幕底部 galgame 对话框窗口 ─────────────────────────────────────────
let dlg = null;

function createDialogue() {
  const wa = screen.getPrimaryDisplay().workArea;
  const w = Math.round(Math.min(wa.width * 0.86, 1280));
  const h = 172;
  dlg = new BrowserWindow({
    x: wa.x + Math.round((wa.width - w) / 2),
    y: wa.y + wa.height - h - 32,
    width: w,
    height: h,
    icon: APP_ICON,
    transparent: true,
    frame: false,
    resizable: false,
    alwaysOnTop: true,
    skipTaskbar: true,
    hasShadow: false,
    fullscreenable: false,
    focusable: true,
    show: false,
    webPreferences: { nodeIntegration: true, contextIsolation: false }
  });
  dlg.setAlwaysOnTop(true, "screen-saver");
  dlg.loadFile("dialogue.html");
  dlg.on("closed", () => { dlg = null; });
}

ipcMain.on("show-dialogue", (_e, text) => {
  if (!dlg) createDialogue();
  const send = () => { if (dlg) dlg.webContents.send("dialogue-text", text); };
  if (dlg.webContents.isLoading()) dlg.webContents.once("did-finish-load", send);
  else send();
  dlg.showInactive();
});
ipcMain.on("close-dialogue", () => { if (dlg) dlg.hide(); });

// ── 单词本：选择保存文件 / 追加保存 / 窗口随列表自动长高 ──────────────────
ipcMain.handle("pick-file", async (_e, current) => {
  const r = await dialog.showSaveDialog(win, {
    title: "选择单词保存文件",
    defaultPath: current || path.join(app.getPath("documents"), "whale-words.txt"),
    filters: [
      { name: "文本文件", extensions: ["txt"] },
      { name: "所有文件", extensions: ["*"] }
    ]
  });
  return r.canceled ? null : r.filePath;
});
ipcMain.handle("append-file", async (_e, { path: filePath, text }) => {
  await fs.promises.appendFile(filePath, text, "utf8");
  return true;
});
ipcMain.on("resize", (_e, { w, h }) => {
  if (!win) return;
  win.setSize(
    Math.max(320, Math.round(w)),
    Math.max(214, Math.min(820, Math.round(h)))
  );
});

// ── 📁 打开文件夹（桌宠上灯泡下面那个按钮）──────────────────────────────
// 先校验路径再交给系统打开，这样渲染进程能拿到「不存在 / 不是文件夹」这类
// 具体原因，用自己的气泡说出来，而不是静默失败。
ipcMain.handle("default-dir", () => defaultOpenDir());

ipcMain.handle("open-dir", async (_e, dir) => {
  const target = String(dir || "").trim();
  if (!target) return { ok: false, error: "还没设定文件夹" };
  let st = null;
  try {
    st = fs.statSync(target);
  } catch (e) {
    return { ok: false, error: "路径不存在" };
  }
  if (!st.isDirectory()) return { ok: false, error: "这不是文件夹" };
  const err = await shell.openPath(target); // 成功时返回空字符串
  return err ? { ok: false, error: err } : { ok: true };
});

// 让用户指定「点一下要打开哪个文件夹」
ipcMain.handle("pick-dir", async (_e, current) => {
  const start = current && fs.existsSync(current) ? current : undefined;
  const r = await dialog.showOpenDialog(win, {
    title: "选择点击后要打开的文件夹",
    defaultPath: start,
    properties: ["openDirectory"]
  });
  return r.canceled || !r.filePaths.length ? null : r.filePaths[0];
});

// ══ 科目清单 / 日程 / 读书材料 ═══════════════════════════════════════════
// 三份数据都放在本应用的 userData 里，自成一体，不依赖别的东西。
// 视觉模型调用不在这里 —— 那个在渲染进程里做，复用原有的 getKey()，
// 省得再加一套密钥存储。
const collator = new Intl.Collator("zh-Hans-CN", { numeric: true, sensitivity: "base" });

function storeFile(name) {
  return path.join(app.getPath("userData"), name);
}

function isDir(p) {
  try { return fs.statSync(p).isDirectory(); } catch (e) { return false; }
}

function readJsonList(file, key) {
  try {
    const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
    const list = Array.isArray(parsed) ? parsed : parsed && parsed[key];
    return Array.isArray(list) ? list : [];
  } catch (e) {
    return []; // 文件不存在或坏了都当空，绝不能因此起不来
  }
}

function writeJsonList(file, key, list) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify({ version: 1, [key]: list }, null, 2), "utf8");
}

/* ---- 📚 科目 ---- */
const foldersFile = () => storeFile("folders.json");

function normalizeFolders(raw) {
  return (Array.isArray(raw) ? raw : [])
    .filter((it) => it && typeof it.path === "string" && it.path.trim())
    .slice(0, 200)
    .map((it, i) => ({
      id: typeof it.id === "string" && it.id ? it.id : "f" + (i + 1),
      name: (typeof it.name === "string" && it.name.trim() ? it.name.trim() : it.path).slice(0, 120),
      path: it.path.trim().slice(0, 1024)
    }));
}

ipcMain.handle("folders-get", () => ({
  ok: true,
  folders: normalizeFolders(readJsonList(foldersFile(), "folders"))
    .map((f) => ({ ...f, exists: isDir(f.path) })),
  file: foldersFile()
}));

ipcMain.handle("folders-set", (_e, list) => {
  try {
    const folders = normalizeFolders(list);
    writeJsonList(foldersFile(), "folders", folders);
    return { ok: true, folders };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

/** 列一个目录下的子目录，给「整批导入」用。 */
ipcMain.handle("subdirs", (_e, dir) => {
  const target = String(dir || "").trim();
  if (!isDir(target)) return { ok: false, error: "路径不存在或不是文件夹" };
  try {
    const dirs = [];
    for (const entry of fs.readdirSync(target, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      dirs.push({ name: entry.name, path: path.join(target, entry.name) });
      if (dirs.length >= 400) break;
    }
    dirs.sort((a, b) => collator.compare(a.name, b.name));
    return { ok: true, dirs, path: target };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

/* ---- 📅 日程 / deadline ---- */
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const TIME_RE = /^\d{2}:\d{2}$/;
const calendarFile = () => storeFile("calendar.json");

function normalizeEvents(raw) {
  return (Array.isArray(raw) ? raw : [])
    .filter((it) => it && typeof it.title === "string" && it.title.trim() && DATE_RE.test(String(it.date || "")))
    .slice(0, 500)
    .map((it, i) => ({
      id: typeof it.id === "string" && it.id ? it.id : "e" + (i + 1),
      title: it.title.trim().slice(0, 160),
      date: String(it.date),
      time: TIME_RE.test(String(it.time || "")) ? String(it.time) : "",
      note: typeof it.note === "string" ? it.note.trim().slice(0, 500) : "",
      done: it.done === true
    }));
}

ipcMain.handle("calendar-get", () => ({
  ok: true,
  events: normalizeEvents(readJsonList(calendarFile(), "events")),
  file: calendarFile()
}));

ipcMain.handle("calendar-set", (_e, list) => {
  try {
    const events = normalizeEvents(list);
    writeJsonList(calendarFile(), "events", events);
    return { ok: true, events };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

/** 系统级提醒：弹一条 Windows 通知。 */
ipcMain.handle("notify", (_e, payload) => {
  try {
    if (!Notification.isSupported()) return { ok: false, error: "系统不支持通知" };
    new Notification({
      title: String((payload && payload.title) || "鲸鱼娘提醒").slice(0, 120),
      body: String((payload && payload.body) || "").slice(0, 400),
      icon: APP_ICON,
      silent: false
    }).show();
    return { ok: true };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

/* ---- 📖 读书材料 ---- */
const IMAGE_EXT = new Set([".png", ".jpg", ".jpeg", ".webp", ".bmp", ".gif", ".tif", ".tiff"]);
const IMAGE_MIME = {
  ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp",
  ".bmp": "image/bmp", ".gif": "image/gif", ".tif": "image/tiff", ".tiff": "image/tiff"
};
const readerCacheFile = () => storeFile("reader-cache.json");

ipcMain.handle("reader-scan", (_e, dir) => {
  const target = String(dir || "").trim();
  if (!isDir(target)) return { ok: false, error: "路径不存在或不是文件夹" };
  try {
    const files = [];
    for (const entry of fs.readdirSync(target, { withFileTypes: true })) {
      if (!entry.isFile()) continue;
      if (!IMAGE_EXT.has(path.extname(entry.name).toLowerCase())) continue;
      const full = path.join(target, entry.name);
      const st = fs.statSync(full);
      files.push({ name: entry.name, path: full, size: st.size, mtime: Math.round(st.mtimeMs) });
      if (files.length >= 500) break;
    }
    files.sort((a, b) => collator.compare(a.name, b.name));
    return { ok: true, dir: target, files };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

ipcMain.handle("reader-read", (_e, file) => {
  const target = String(file || "").trim();
  try {
    const bytes = fs.readFileSync(target);
    const mime = IMAGE_MIME[path.extname(target).toLowerCase()] || "application/octet-stream";
    return { ok: true, dataUrl: "data:" + mime + ";base64," + bytes.toString("base64") };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

ipcMain.handle("reader-cache-get", () => {
  try { return { ok: true, cache: JSON.parse(fs.readFileSync(readerCacheFile(), "utf8")) }; }
  catch (e) { return { ok: true, cache: {} }; }
});

ipcMain.handle("reader-cache-set", (_e, cache) => {
  try {
    fs.writeFileSync(readerCacheFile(), JSON.stringify(cache || {}, null, 2), "utf8");
    return { ok: true };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

/** 把结果写成一份 markdown 索引，放在被读的那个文件夹里。 */
ipcMain.handle("reader-write-index", (_e, payload) => {
  const dir = String((payload && payload.dir) || "").trim();
  const entries = Array.isArray(payload && payload.entries) ? payload.entries : [];
  if (!isDir(dir)) return { ok: false, error: "文件夹不存在了" };
  const esc = (v) => String(v == null ? "" : v).replace(/\|/g, "\\|");
  const lines = [
    "# 鲸鱼娘读图索引",
    "",
    "由「鲸鱼娘 桌宠」的读书材料片段分析生成。短名和说明都由视觉模型读图后给出，",
    "用来检索这些片段；原文件名保持不变。",
    "",
    `共 ${entries.length} 条。`,
    "",
    "| 短名 | 说明 | 文件 |",
    "| --- | --- | --- |",
    ...entries.map((it) => `| ${esc(it.name)} | ${esc(it.note)} | \`${esc(it.file)}\` |`),
    ""
  ];
  const target = path.join(dir, "_鲸鱼娘索引.md");
  try {
    fs.writeFileSync(target, lines.join("\n"), "utf8");
    return { ok: true, file: target };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
});

// 单实例：重复启动时退出新实例，并把已有鲸鱼娘带到前台（防止按钮连点开多个）
if (!app.requestSingleInstanceLock()) {
  app.quit();
} else {
  app.on("second-instance", () => {
    if (!win) return;
    if (win.isMinimized()) win.restore();
    win.show();
    win.focus();
  });
  app.whenReady().then(createWindow);
  app.on("window-all-closed", () => { if (process.platform !== "darwin") app.quit(); });
}
